function PF_CLEANROOM() {
    if (PF_CR !== null) return PF_CR
    try { PF_CR = CleanroomType.CLEANROOM }
    catch (e1) { PF_CR = Java.loadClass('com.gregtechceu.gtceu.api.machine.multiblock.CleanroomType').CLEANROOM }
    return PF_CR
}

